<script lang="ts">
  import Icon from './Icon.svelte';
  import { faArrowRight, faArrowsRotate, faBoxOpen, faClock, faShareNodes, faShieldHalved, faSliders, faStop, faTowerBroadcast, faUsers, faVolumeHigh } from '@fortawesome/free-solid-svg-icons';
  import { phases, type RoomView } from '../../shared/types';
  import { scenes, phaseLabels, npcs, routes, objectiveLabels, debriefPrompts } from '../../shared/content';
  import { locale } from '../lib/i18n';
  import { command, busy, connection } from '../lib/client';
  import { onDestroy, untrack } from 'svelte';
  import CheckPanel from './CheckPanel.svelte';
  import PollPanel from './PollPanel.svelte';
  import Evidence from './Evidence.svelte';
  import People from './People.svelte';
  import Handover from './Handover.svelte';
  import Debrief from './Debrief.svelte';
  import Seascape from './Seascape.svelte';
  let { game, gm = false, onshare }: { game: RoomView; gm?: boolean; onshare: () => void } = $props();
  let speaking = $state(false), customPlan = $state(''), customCosts = $state(''), customAssumptions = $state('');
  let settingMode = $state(untrack(() => game.settings.mode)), settingDice = $state(untrack(() => game.settings.dice)), settingGms = $state(untrack(() => game.settings.gmCount));
  const t = (zh: string, en: string) => $locale === 'zh-CN' ? zh : en;
  const locked = $derived($busy || $connection !== 'live');
  const scene = $derived(game.phase === 'lobby' ? null : scenes[game.phase]);
  const poll = $derived(game.polls.filter(p => game.phase === 'negotiation' ? p.kind === 'decision' : game.phase === 'route_choice' ? p.kind === 'route' : game.phase === 'execution' ? p.kind === 'kit' && p.checkId === game.checks.at(-1)?.id : false).at(-1));
  const blocked = $derived(game.checks.some(c => c.status !== 'resolved') || game.polls.some(p => p.status === 'open' || (p.tied.length > 0 && !p.outcome)));
  const incomplete = $derived(game.phase === 'investigation' && game.settings.mode === 'full' ? game.checks.filter(c => c.kind === 'preparation' && c.result).length < 3 : game.phase === 'execution' ? game.checks.filter(c => c.kind === 'execution' && c.result).length < 3 : game.phase === 'route_choice' ? !game.route : game.phase === 'lobby' ? !game.members.some(m => m.role === 'player') || game.members.filter(m => m.role === 'gm').length < game.settings.gmCount : game.phase === 'ending' ? !game.report.owner.trim() || !game.report.nextUpdate.trim() || !game.report.statement.trim() : false);
  function read() {
    if (!('speechSynthesis' in window) || !scene) return;
    if (speaking) { speechSynthesis.cancel(); speaking = false; return; }
    const utterance = new SpeechSynthesisUtterance(`${scene.body[$locale]} ${scene.prompt[$locale]}`); utterance.lang = $locale === 'zh-CN' ? 'zh-CN' : 'en-US';
    utterance.onend = utterance.onerror = () => speaking = false;
    speaking = true; speechSynthesis.speak(utterance);
  }
  $effect(() => { game.phase; if ('speechSynthesis' in window) speechSynthesis.cancel(); speaking = false; });
  onDestroy(() => { if ('speechSynthesis' in window) speechSynthesis.cancel(); });
</script>
{#if game.phase === 'lobby'}
  <section class="lobby-welcome"><div><span class="tiny-tag">{t('The Shell · 救援集结', 'The Shell · Rescue assembly')}</span><h1>{t('让我们一起，', 'Together,')}<br />{t('把他们带回来。', 'bring them home.')}</h1><p>{t('房间已经准备就绪。邀请同伴加入，选择分工，等主持人宣布任务。', 'Your room is ready. Invite your teammates, choose your roles and wait for the mission briefing.')}</p><button class="btn primary" onclick={onshare}><Icon icon={faShareNodes} size={17} />{t('邀请同伴', 'Invite the team')}<span class="code-inline">{game.code}</span></button></div><div class="lobby-art"><Seascape compact /></div></section>
  <div class="lobby-settings-summary"><span><Icon icon={faClock} size={17} />{game.settings.mode === 'full' ? t('完整 · 45 + 10 分钟', 'Full · 45 + 10 minutes') : t('精简 · 20 + 5 分钟', 'Short · 20 + 5 minutes')}</span><span><Icon icon={faUsers} size={17} />{game.settings.gmCount} {game.settings.gmCount === 2 ? 'Co-GMs' : 'GMs'}</span><span><Icon icon={faBoxOpen} size={17} />{t('两份共享应急物资', 'Two shared emergency kits')}</span><span>{game.settings.dice === 'physical' ? t('实体 D20 · GM 录入', 'Physical D20 · GM enters') : t('虚拟 D20 · 系统掷骰', 'Virtual D20 · server rolls')}</span></div>
  <People {game} {gm} />
  {#if gm}<details class="gm-details surface"><summary><Icon icon={faSliders} size={16} />{t('房间规则与主持席位', 'Room rules & GM seats')}</summary><form onsubmit={(e) => { e.preventDefault(); command('settings', { mode: settingMode, dice: settingDice, gmCount: settingGms }); }}><div class="form-row"><div><label for="setting-gms">{t('主持人数', 'GM count')}</label><select id="setting-gms" bind:value={settingGms}>{#each [1,2,3,4] as n}<option value={n}>{n}</option>{/each}</select></div><div><label for="setting-mode">{t('剧本', 'Story')}</label><select id="setting-mode" bind:value={settingMode}><option value="full">{t('完整', 'Full')}</option><option value="short">{t('精简', 'Short')}</option></select></div><div><label for="setting-dice">{t('骰子', 'Dice')}</label><select id="setting-dice" bind:value={settingDice}><option value="virtual">{t('虚拟', 'Virtual')}</option><option value="physical">{t('实体', 'Physical')}</option></select></div></div><button class="btn secondary" disabled={locked}>{t('保存设置', 'Save settings')}</button></form><p>{t('本场约定：D20 加一项相关加成（工具 +1 / 工程 +2 / 领导力 +3）；准备与创意最多降 DC 2，取较高者；自然 1 无额外处罚。', 'Session conventions: D20 plus one relevant bonus (tool +1 / engineering +2 / leadership +3). Use the greater preparation or creative reduction, up to 2. Natural 1 has no extra penalty.')}</p></details>{/if}
{:else if scene}
  <section class="scene-intro"><div class="scene-meta"><span class="tiny-tag">{t('当前章节', 'Current chapter')} {String(phases.indexOf(game.phase)).padStart(2, '0')} / 07</span>{#if 'speechSynthesis' in window}<button class="read-button" onclick={read}>{#if speaking}<Icon icon={faStop} size={14} />{:else}<Icon icon={faVolumeHigh} size={16} />{/if}{speaking ? t('停止朗读', 'Stop reading') : t('朗读背景', 'Read aloud')}</button>{/if}</div><h1>{scene.title[$locale]}</h1><p class="scene-narrative">{scene.body[$locale]}</p><div class="scene-prompt"><Icon icon={faTowerBroadcast} size={18} /><p>{scene.prompt[$locale]}</p></div></section>
  {#if game.phase === 'briefing'}<div class="briefing-visual"><Seascape /><div class="briefing-overlay"><span>{t('现场时间', 'Story time')}<strong>17:40</strong></span><span>{t('预计暴潮', 'Surge expected')}<strong>17:52</strong></span><span>{t('受困工人', 'Workers inside')}<strong>12</strong></span></div></div><div class="safeguards"><h3><Icon icon={faShieldHalved} size={19} />{t('出发前，确认你们已有的保障', 'Before you go, know your safeguards')}</h3><p>{t('4 人上层避难室，约两小时保障。诊所独立备用电源 20 分钟。两份全组应急物资。额定 8 人工作艇（含 2 名船员），两趟可运 12 人。', 'Upper refuge: 4 people, roughly two hours. Independent clinic backup: 20 minutes. Two shared emergency kits. An 8-person-rated boat, including 2 crew; two trips can evacuate 12 people.')}</p><small>{t('十二分钟是故事时间；课堂讨论不会偷偷消耗行动窗口。', 'The twelve minutes are fictional. Discussion does not secretly consume action windows.')}</small></div>
  {:else if game.phase === 'investigation'}<Evidence {game} inline />{#if game.settings.mode === 'full'}<CheckPanel {game} {gm} />{:else}<div class="inline-info"><Icon icon={faUsers} size={21} /><p>{t('精简版共享全部线索，跳过准备骰。两份物资保留，执行基础 DC 为 12 / 12 / 13，创意仍可最多降低 2。', 'Short mode shares all evidence and skips preparation rolls. Keep both kits. Execution DCs remain 12 / 12 / 13, with creative reductions up to 2.')}</p></div>{/if}
  {:else if game.phase === 'negotiation'}<div class="npc-grid">{#each npcs as npc, i}<article class="npc-card"><div class="npc-head"><span class="npc-avatar">{npc.name.slice(0, 1)}</span><div><h3>{npc.name}</h3><small>{npc.guild} · {npc.job[$locale]}</small></div><span class="signal-dot"></span></div><blockquote>{npc.dialogue[$locale]}</blockquote><p>{npc.boundary[$locale]}</p></article>{/each}</div>{#if poll}<PollPanel {game} {poll} {gm} />{/if}
  {:else if game.phase === 'route_choice'}<div class="route-cards">{#each routes.filter(r => r.id !== 'custom' || game.customRoute.plan) as route}<article class:route-selected={game.route === route.id}><span class="route-letter">{route.label}</span><h3>{route.title[$locale]}</h3>{#if $locale === 'zh-CN'}<small>{route.english}</small>{/if}<p>{route.id === 'custom' ? game.customRoute.plan : route.method[$locale]}</p><div><strong>{t('公开代价', 'Known costs')}</strong><ul>{#if route.id === 'custom'}<li>{game.customRoute.costs}</li>{:else}{#each route.costs as cost}<li>{cost[$locale]}</li>{/each}{/if}</ul></div>{#if route.id === 'custom'}<p class="field-hint">{t('假设：', 'Assumptions: ')}{game.customRoute.assumptions}</p>{/if}</article>{/each}</div>{#if poll}<PollPanel {game} {poll} {gm} />{/if}
    {#if gm}<details class="gm-details surface"><summary>{t('混合 / 自创路线，或重新投票', 'Custom route / restart the vote')}</summary><form onsubmit={(e) => { e.preventDefault(); command('custom_route', { plan: customPlan, costs: customCosts, assumptions: customAssumptions }); }}><label for="custom-plan">{t('三个目标如何完成', 'How will all three objectives be met?')}</label><textarea id="custom-plan" bind:value={customPlan} maxlength="2000" required></textarea><label for="custom-costs">{t('接受的公开代价', 'Accepted public costs')}</label><textarea id="custom-costs" bind:value={customCosts} maxlength="2000" required></textarea><label for="custom-assumptions">{t('需要验证的假设', 'Assumptions to verify')}</label><textarea id="custom-assumptions" bind:value={customAssumptions} maxlength="2000" required></textarea><button class="btn secondary" disabled={locked}>{t('保存自创方案', 'Save custom route')}</button></form><p>{t('保存方案会自动重新开放投票，所有人需确认新的方案与代价。', 'Saving the plan automatically reopens voting. Everyone must approve the new plan and costs.')}</p><button class="btn secondary" disabled={locked} onclick={() => command('route_vote')}><Icon icon={faArrowsRotate} size={15} />{t('重新发起路线投票', 'Restart route vote')}</button></details>{/if}
  {:else if game.phase === 'execution'}{#if game.route}<div class="selected-route-strip"><span>{t('已选路线', 'Selected route')}</span><strong>{routes.find(r => r.id === game.route)?.title[$locale]}</strong><span>{t('三个目标 · 每项一次检定', 'Three objectives · one check each')}</span></div>{/if}<CheckPanel {game} {gm} />{#if poll}<PollPanel {game} {poll} {gm} />{/if}
  {:else if game.phase === 'ending'}<Handover {game} {gm} />
  {:else if game.phase === 'debrief'}<Debrief {game} /><details class="ending-review"><summary>{t('回看事故交接与救援结果', 'Review the handover and rescue outcomes')}</summary><Handover {game} {gm} /></details>{/if}
{/if}
{#if gm && game.gmContext && game.phase !== 'lobby'}<details class="private-context"><summary>{t('主持人提示 · 仅 GM 可见', 'Facilitator notes · GMs only')}</summary>{#each game.gmContext as hint}<p><strong>{hint.name}</strong> {hint.context[$locale]}</p>{/each}</details>{/if}
{#if gm && game.phase !== 'debrief'}<div class="advance-bar"><div><strong>{game.phase === 'lobby' ? t('所有人准备好了吗？', 'Is everyone ready?') : t('留一点空间，听听每个人。', 'Make room for every voice.')}</strong><p>{blocked ? t('先完成当前投票或检定。', 'Finish the current vote or check.') : incomplete ? game.phase === 'lobby' ? t('请补齐主持席位，并至少加入一名玩家。', 'Fill the GM seats and add at least one player.') : game.phase === 'ending' ? t('请保存通报原话、负责人和更新时间。', 'Save the statement, owner and update time.') : t('完成当前阶段的目标后继续。', 'Complete this stage’s objectives to continue.') : t('继续会为所有人更新背景与下一步任务。', 'Continue to share the next scene and task with everyone.')}</p></div><button class="btn primary" disabled={locked || blocked || incomplete} onclick={() => command('next')}>{game.phase === 'lobby' ? t('开始任务', 'Begin the mission') : phaseLabels[phases[phases.indexOf(game.phase) + 1]][$locale]}<Icon icon={faArrowRight} size={18} /></button></div>{/if}
